'use client'

let loadPromise: Promise<unknown> | null = null

export const loadHypertube = async () => {
  if (typeof window === 'undefined') {
    throw new Error('Hypertube SDK is only available in the browser.')
  }
  if (!loadPromise) {
    loadPromise = import('hypertube-nodejs-sdk')
  }
  return loadPromise
}
